import{_ as o,o as u,c as q,ag as a}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"金刚经7分-非法非非法","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经7分-非法非非法.md","filePath":"60-原文段落/金刚经7分-非法非非法.md","lastUpdated":1778155802000}'),e={name:"60-原文段落/金刚经7分-非法非非法.md"};function r(_,t,s,p,n,c){return u(),q("div",null,[...t[0]||(t[0]=[a('<h1 id="金刚经7分-非法非非法" tabindex="-1">金刚经7分-非法非非法 <a class="header-anchor" href="#金刚经7分-非法非非法" aria-label="Permalink to &quot;金刚经7分-非法非非法&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/7了空居士讲《金刚经》-第七分无得无说分20161014">7了空居士讲《金刚经》-第七分无得无说分20161014</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>何以故？如来所说法，皆不可取，不可说，非法，非非法。</strong></p><p>噢，这个&quot;何以故&quot;也是须菩提说的，它前面是：须菩提&quot;如我解佛所说义，无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说, 何以故&quot;从这里看得出这些话，全部是须菩提说的。噢，就反过来。我们有些人说，那佛祖你不是说了很多话吗？而且我们后世还结集成经典啊，就我们面前的这个《金刚经》，就是你如来所说嘛，那你又为什么说如来&quot;无有定法如来可说&quot;？你看，《金刚经》是针对须菩提的提问，世尊给他解答的。就是说，如来说的这些话你们&quot;不可取&quot;。你们说：这个事情不可取，就是说没用啊，不能这么做。这里的&quot;不可取&quot;是不是这个意思啊？不是！这个&quot;不可取&quot;的意思就是不能照搬硬套，如来说的这些都是针对性的，你们如果换一个场合，换一个时间，可能就不能这么套进去了。就是说&quot;不可取&quot;的意思就是不能落入教条主义，不要说&quot;取&quot;过来，就来&quot;套&quot;进去用，不能这么做。</p><p>&quot;皆不可取，不可说&quot;，&quot;说&quot;的意思就是你依样画葫芦地说给别人去，其实&quot;取&quot;就是自己听过来去照搬硬套，&quot;说&quot;就是你用这个方法去教别人去教条主义，是这个意思。</p><p><strong>非法，非非法。</strong></p><p>&quot;非法&quot;直接翻译过来就是&quot;不是法&quot;，&quot;非非法&quot;就&quot;不是不是法&quot;。&quot;不是法&quot;是什么意思？就是说落空。就说那些都没用了，没用的东西，其实不是。&quot;非法&quot;就是说不是方法啊，也等于说是没用的。不要以为是&quot;不可取&quot;的，是没用的，不是，不是。好像你拿一把锁匙开这个锁开的出来，但是你这把锁是拿去开其他的锁——严格来说哈，那些质量不好的锁,什么钥匙都开得出来，就不要说了啊——嗯，如果是精密度好的锁，是真的这把锁匙开这个锁，但是你拿去开其他锁是开不出来的。所以拿一把钥匙说这是锁匙吗？你说是啊，那这么说是能开我这个锁吗？唉，不是开这个锁的就开不出来了啊。所以说:是锁匙非锁匙，是名锁匙，就是这个意思啊。就是说它不是通用的。所以说这个&quot;非法&quot;就是说如来所说的这些道理，不是一个绝对的道理，它是相对的，它是针对某一个具体的事情是有效的，对另外一个事情也许是无效的，这就是&quot;非法&quot;的真实义。</p><p>&quot;非非法&quot;，就是说，&quot;非非&quot;就是否定之否定，就是说&quot;也不是&quot;——前面说&quot;非法&quot;就是&quot;不是方法&quot;——&quot;非非法&quot;，不是不是方法，就是说：你也不能倒过来，就觉得一定是有用的，也就是说，你不能认为这个方法一定是有用的，或者是一定是没用的，不能这么认为，而是说它是具体的应用，有针对性的那个就有用的，如果偏离了这个方面，他就没有用了啊，是这个意思。</p>',9)])])}const l=o(e,[["render",r]]);export{d as __pageData,l as default};
